def completar_horas(apps, schema_editor):
    """Retiros y pagos existentes: la hora se toma de su timestamp, en hora local."""
    from django.utils import timezone

    Retiro = apps.get_model("agenda", "Retiro")
    Pago = apps.get_model("agenda", "Pago")
    for r in Retiro.objects.filter(hora__isnull=True):
        r.hora = timezone.localtime(r.registrado_en).time().replace(second=0, microsecond=0)
        r.save(update_fields=["hora"])
    for p in Pago.objects.filter(hora__isnull=True):
        p.hora = timezone.localtime(p.creado_en).time().replace(second=0, microsecond=0)
        p.save(update_fields=["hora"])


